function reducer(state, action){
  switch(action.type){
    case 'NAV': return {...state, activeScreen:action.screen};
    case 'SELECT_REC': return {...state, selectedRecId:action.id, activeScreen:'recommendation_evidence_panel'};
    case 'OPEN_PROVENANCE': return {...state, selectedEvidence:action.ev, activeScreen:'source_provenance_view'};
    case 'SELECT_THEME': return {...state, selectedTheme:action.theme, activeScreen:'sentiment_trend_explorer'};
    case 'ADD_EXPORT': return {...state, exportDraft: state.exportDraft.includes(action.id)?state.exportDraft:[...state.exportDraft, action.id], toast:'Added to export — '+action.id};
    case 'REMOVE_EXPORT': return {...state, exportDraft: state.exportDraft.filter(x=>x!==action.id)};
    case 'SET_FORMAT': return {...state, exportFormat:action.fmt};
    case 'SET_EXPORT_PROGRESS': return {...state, exportProgress:action.v};
    case 'EXPORT_DONE': return {...state, exportProgress:100, exportFileName:action.file, toast:'Exported '+action.file};
    case 'TOAST': return {...state, toast:action.msg};
    case 'CLEAR_TOAST': return {...state, toast:null};
    case 'ADD_FLAG': return {...state, flags:[{id:'flg-'+(state.flags.length+1),recommendation_id:action.id,note:action.note,assignee:'Marcus Vance',gap_reason:action.gap,status:'open',created_at:new Date().toISOString()}, ...state.flags], toast:'Flagged for review', activeScreen:'rising_signals_and_flags', signalsTab:'flags'};
    case 'RESOLVE_FLAG': return {...state, flags: state.flags.map(f=>f.id===action.id?{...f,status:'resolved'}:f)};
    case 'SIGNALS_TAB': return {...state, signalsTab:action.tab};
    case 'SET_WATCH': {
      const w = state.watch.map(x=>x.id===action.id?{...x,threshold:action.threshold,triggered:x.current_confidence>=action.threshold}:x);
      const crossed = w.find(x=>x.id===action.id && x.triggered);
      return {...state, watch:w, alertBanner: crossed?{theme:crossed.theme,conf:crossed.current_confidence}:state.alertBanner};
    }
    case 'CLEAR_ALERT': return {...state, alertBanner:null};
    case 'REFRESH': return {...state, activeScreen:'refresh_diff_view', lastRefresh:new Date().toLocaleString()};
    case 'AI_STATUS': return {...state, aiStatus:{...state.aiStatus,[action.flow]:action.status}};
    case 'TOGGLE_CONF': return {...state, reducedConfidenceExpanded:!state.reducedConfidenceExpanded};
    default: return state;
  }
}

// ── multi-provider AI helper (fallback path) ──
async function callAI(flow, dispatch){
  const providers=['/api/ai/gemini-compat','/api/ai/anthropic'];
  dispatch({type:'AI_STATUS',flow,status:{state:'loading'}});
  for(let i=0;i<providers.length;i++){
    try{
      const ctl=new AbortController(); const t=setTimeout(()=>ctl.abort(),9000);
      const r=await fetch(providers[i],{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({flow}),signal:ctl.signal});
      clearTimeout(t);
      if(!r.ok) throw new Error('bad');
      dispatch({type:'AI_STATUS',flow,status:{state:'ok',provider:providers[i]}});
      return await r.json();
    }catch(e){ if(i===providers.length-1){ dispatch({type:'AI_STATUS',flow,status:{state:'ok',provider:'cached',note:'served from seed (fallback)'}}); return null; } }
  }
}

