function ConfRing({score,size=44,reveal=true}){
  const r=(size-7)/2, c=2*Math.PI*r, dash=c*(reveal?score:0);
  const col = score>=0.8?TOK.success:score>=0.65?TOK.cyan:score>=0.5?TOK.warn:TOK.error;
  return (
    <svg width={size} height={size} role="img" aria-label={'Confidence '+score.toFixed(2)}>
      <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={TOK.ecru} strokeWidth={3.5}/>
      <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={col} strokeWidth={3.5} strokeLinecap="round"
        strokeDasharray={dash+' '+c} transform={'rotate(-90 '+size/2+' '+size/2+')'} style={{transition:'stroke-dasharray .6s cubic-bezier(.4,0,.2,1)'}}/>
    </svg>
  );
}

function CoveragePill({status}){
  const m={full:[TOK.success,'Full'],partial:[TOK.warn,'Partial'],thin:[TOK.error,'Thin']}[status]||[TOK.grey,status];
  return <span className="data" style={{fontSize:10.5,padding:'3px 8px',borderRadius:999,border:'1px solid '+m[0],color:m[0]}}>◆ {m[1]} coverage</span>;
}
function ContestedBadge(){
  return <span className="data" style={{fontSize:10.5,padding:'3px 8px',borderRadius:999,border:'1px solid '+TOK.rust,color:TOK.rust,display:'inline-flex',alignItems:'center',gap:4}}><Icon name="AlertTriangle" size={11}/>Contested</span>;
}
function AIProvenance({status}){
  if(!status) return null;
  const txt = status.state==='loading' ? 'AI working…' : status.state==='ok' ? ('AI · '+(status.provider||'').replace('/api/ai/','')+(status.note?' · '+status.note:'')) : 'AI fallback';
  return <span className="data" style={{fontSize:10,color:TOK.cyan}}>{txt}</span>;
}
function Toast({state,dispatch}){
  useEffect(()=>{ if(state.toast){ const t=setTimeout(()=>dispatch({type:'CLEAR_TOAST'}),2600); return ()=>clearTimeout(t);} },[state.toast]);
  if(!state.toast) return null;
  return <div role="status" aria-live="polite" style={{position:'fixed',bottom:24,left:'50%',transform:'translateX(-50%)',background:TOK.rail,color:TOK.paper,padding:'12px 20px',borderRadius:2,display:'flex',alignItems:'center',gap:8,zIndex:200,fontFamily:FONT.body,fontSize:14}}><Icon name="Check" size={16} color={TOK.success}/>{state.toast}</div>;
}
function AlertBanner({state,dispatch}){
  if(!state.alertBanner) return null;
  return <div role="status" style={{background:TOK.washWarn,borderBottom:'1px solid '+TOK.rust,padding:'12px 40px',display:'flex',alignItems:'center',gap:12}}><Icon name="Bell" size={16} color={TOK.rust}/><span className="bodytx" style={{color:TOK.ink}}><b>Watch crossed:</b> {state.alertBanner.theme} reached {state.alertBanner.conf.toFixed(2)}.</span><button className="btn-link focusable" onClick={()=>dispatch({type:'CLEAR_ALERT'})}>Dismiss</button></div>;
}

