// PATTERN MANIFEST: p-rec, p-trail, p-counterfactual, p-hitl (proto/Accordion, proto/Progress, proto/Badge, proto/Skeleton, proto/Card, proto/Alert, proto/List)

function Screen_recommendation_evidence_panel({ state, dispatch }) {
  const rec = state.recommendations.find(r => r.id === state.selectedRecId) || state.recommendations[0];
  const [confExpanded, setConfExpanded] = useState(state.reducedConfidenceExpanded);
  const [openClusters, setOpenClusters] = useState({});
  const [confReveal, setConfReveal] = useState(false);
  const [confTotal, setConfTotal] = useState(0);

  useEffect(() => { callAI('evidence_recommendation_linking', dispatch); }, [rec.id]);

  // evidence for active rec, grouped by cluster
  const evList = useMemo(
    () => state.evidence.filter(e => e.recommendation_id === rec.id),
    [state.evidence, rec.id]
  );
  const clusterOrder = ['Market Reports', 'Sentiment', 'Competitor Signals', 'Internal Annotations'];
  const clusters = useMemo(() => {
    const m = {};
    evList.forEach(e => { (m[e.cluster] = m[e.cluster] || []).push(e); });
    return clusterOrder.filter(c => m[c]).map(c => [c, m[c]]);
  }, [evList]);

  // contribution factors: seeded or computed
  const contrib = useMemo(() => {
    if (state.contrib[rec.id]) return state.contrib[rec.id];
    if (!evList.length) return [];
    const avg = (f) => evList.reduce((s, e) => s + f(e), 0) / evList.length;
    const relAvg = avg(e => e.relevance_score);
    const recAvg = 1 - Math.min(1, avg(e => e.recency_days) / 90);
    const cntScore = Math.min(1, evList.length / 10);
    const dirs = evList.map(e => e.signal_direction);
    const agree = dirs.filter(d => d === 'supporting').length / dirs.length;
    return [
      { factor: 'Source count', weight: 0.3, value: cntScore },
      { factor: 'Source quality', weight: 0.3, value: relAvg },
      { factor: 'Recency', weight: 0.2, value: recAvg },
      { factor: 'Signal agreement', weight: 0.2, value: agree }
    ];
  }, [rec.id, evList, state.contrib]);

  // count-up animation for total confidence on expand
  useEffect(() => {
    if (!confExpanded) { setConfReveal(false); setConfTotal(0); return; }
    setConfReveal(true);
    const target = rec.confidence_score;
    const start = performance.now();
    let raf;
    const tick = (now) => {
      const t = Math.min(1, (now - start) / 600);
      setConfTotal(target * t);
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [confExpanded, rec.id, rec.confidence_score]);

  const loading = state.aiStatus.evidence_recommendation_linking?.state === 'loading';

  const supporting = evList.filter(e => e.signal_direction === 'supporting').length;
  const contradicting = evList.filter(e => e.signal_direction === 'contradicting').length;
  const constraining = evList.filter(e => e.signal_direction === 'constraining').length;

  // word-safe truncation (never mid-word ellipsize)
  function truncate(s, max) {
    if (s.length <= max) return s;
    let cut = s.slice(0, max);
    const sp = cut.lastIndexOf(' ');
    if (sp > 0) cut = cut.slice(0, sp);
    return cut + '…';
  }

  function toggleConf() {
    setConfExpanded(v => !v);
    dispatch({ type: 'TOGGLE_CONF' });
  }
  function toggleCluster(c) { setOpenClusters(o => ({ ...o, [c]: !o[c] })); }
  function clusterKey(e, c) {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleCluster(c); }
  }

  const dirMeta = {
    supporting: { col: TOK.success, gl: '▲', lbl: 'Supporting' },
    contradicting: { col: TOK.error, gl: '▼', lbl: 'Contradicting' },
    constraining: { col: TOK.warn, gl: '◆', lbl: 'Constraining' }
  };

  // find an attitudinal sentiment evidence item to offer Sentiment-trend route
  const sentEv = evList.find(e => e.type === 'sentiment');

  function onFlag() {
    callAI('flag_gap_reason', dispatch);
    const gap = rec.contested
      ? 'directional disagreement across sources'
      : rec.coverage_status === 'thin'
        ? 'single source, no sentiment corroboration'
        : 'coverage gap flagged for analyst review';
    dispatch({
      type: 'ADD_FLAG',
      id: rec.id,
      note: 'Analyst review requested for ' + rec.title,
      gap
    });
  }

  return (
    <div style={{ display: 'flex', gap: 0, alignItems: 'flex-start', padding: '28px 40px', maxWidth: 1320, margin: '0 auto' }}>

      {/* ── LEFT: pinned recommendation card ── */}
      <div style={{ width: 360, flexShrink: 0, position: 'sticky', top: 16 }}>
        <div className="cardbox cascade" style={{ padding: 20 }}>
          <div className="kicker" style={{ marginBottom: 14 }}>Recommendation · Rank {rec.rank}</div>
          <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start', marginBottom: 14 }}>
            <ConfRing score={rec.confidence_score} size={56} reveal={true} />
            <div style={{ flex: 1 }}>
              <div className="data" style={{ fontSize: 22, color: TOK.ink, lineHeight: 1 }}>{rec.confidence_score.toFixed(2)}</div>
              <div className="lbl" style={{ marginTop: 2 }}>{rec.theme}</div>
            </div>
          </div>
          <div className="disp" style={{ fontSize: 21, color: TOK.ink, marginBottom: 10 }}>{rec.title}</div>
          <p className="bodytx" style={{ fontSize: 13.5, marginBottom: 14 }}>{rec.thesis}</p>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 16 }}>
            <CoveragePill status={rec.coverage_status} />
            {rec.contested && <ContestedBadge />}
            <span className="data" style={{ fontSize: 10.5, padding: '3px 8px', borderRadius: 999, border: '1px solid ' + TOK.hairline, color: TOK.grey }}>
              {rec.evidence_count} sources · impact {rec.impact_score}
            </span>
          </div>

          {/* Confidence & coverage expander (proto/Accordion + proto/Progress) */}
          <div style={{ border: '1px solid ' + TOK.hairline, borderRadius: 6 }}>
            <button
              className="focusable"
              onClick={toggleConf}
              aria-expanded={confExpanded}
              style={{ width: '100%', display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 12px', background: 'none', border: 'none', cursor: 'pointer' }}>
              <span className="lbl" style={{ color: TOK.ink }}>Confidence &amp; coverage</span>
              <Icon name={confExpanded ? 'Minus' : 'Plus'} size={15} color={TOK.grey} />
            </button>
            {confExpanded && (
              <div style={{ padding: '0 12px 14px' }}>
                {contrib.map((c, i) => (
                  <div key={c.factor} style={{ marginBottom: 12 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                      <span className="bodytx" style={{ fontSize: 12, color: TOK.secondary }}>{c.factor} <span className="data" style={{ color: TOK.muted, fontSize: 10.5 }}>· w{c.weight.toFixed(1)}</span></span>
                      <span className="data" style={{ fontSize: 11.5, color: TOK.ink }}>{c.value.toFixed(2)}</span>
                    </div>
                    <div role="progressbar" aria-valuenow={Math.round(c.value * 100)} aria-valuemin={0} aria-valuemax={100}
                      style={{ height: 7, borderRadius: 999, background: TOK.panel, overflow: 'hidden' }}>
                      <div style={{
                        height: '100%', borderRadius: 999, background: TOK.cyan,
                        width: confReveal ? (c.value * 100) + '%' : 0,
                        transition: 'width .5s cubic-bezier(.4,0,.2,1)', transitionDelay: (i * 0.12) + 's'
                      }} />
                    </div>
                  </div>
                ))}
                <div style={{ borderTop: '1px solid ' + TOK.hairline, paddingTop: 10, marginTop: 4, display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
                  <span className="lbl" style={{ color: TOK.ink }}>Composite</span>
                  <span className="data" style={{ fontSize: 18, color: TOK.ink }}>{confTotal.toFixed(2)}</span>
                </div>
                {rec.contested && (
                  <p className="bodytx" style={{ fontSize: 11.5, color: TOK.rust, marginTop: 8 }}>
                    Contested — directional signals are shown side-by-side, never averaged.
                  </p>
                )}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* ── RIGHT: slide-over evidence panel ── */}
      <div className="cardbox" style={{ flex: 1, marginLeft: 24, animation: 'slideIn .4s cubic-bezier(.4,0,.2,1)', overflow: 'hidden' }}>
        {/* header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '16px 20px', borderBottom: '1px solid ' + TOK.hairline, background: TOK.panel }}>
          <div>
            <div className="kicker" style={{ marginBottom: 4 }}>Evidence trail</div>
            <div className="disp" style={{ fontSize: 17, color: TOK.ink }}>{evList.length} cited passages · {clusters.length} clusters</div>
          </div>
          <button className="btn focusable" onClick={() => dispatch({ type: 'NAV', screen: 'outlook_overview' })}>
            <Icon name="X" size={15} /> Close
          </button>
        </div>

        <div style={{ padding: 20 }}>
          <div style={{ marginBottom: 14, display: 'flex', alignItems: 'center', gap: 10 }}>
            <AIProvenance status={state.aiStatus.evidence_recommendation_linking} />
          </div>

          {/* contested dissent callout (proto/Alert) */}
          {rec.contested && (
            <div role="alert" style={{ background: TOK.washWarn, borderLeft: '3px solid ' + TOK.rust, border: '1px solid ' + TOK.hairline, borderLeftWidth: 3, borderRadius: 6, padding: '12px 14px', marginBottom: 18 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
                <Icon name="AlertTriangle" size={15} color={TOK.rust} />
                <span className="lbl" style={{ color: TOK.rust }}>Contested — both sides shown</span>
              </div>
              <p className="bodytx" style={{ fontSize: 12.5, color: TOK.ink }}>
                {supporting} supporting vs {contradicting} contradicting signal{contradicting !== 1 ? 's' : ''}{constraining ? ' (plus ' + constraining + ' constraining)' : ''}. Sources diverge on the rollout path — the upside is real but the pace is disputed, so frame this for the board as phased rather than settled.
              </p>
            </div>
          )}

          {/* loading skeleton */}
          {loading && (
            <div aria-busy="true" style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {[0, 1, 2].map(i => (
                <div key={i} className="shimmer" style={{ height: 56, borderRadius: 6 }} aria-hidden="true" />
              ))}
            </div>
          )}

          {/* clusters accordion (proto/Accordion + proto/List) */}
          {!loading && clusters.map(([name, items]) => {
            const isInternal = name === 'Internal Annotations';
            const open = openClusters[name];
            return (
              <div key={name} style={{
                marginBottom: 12,
                border: '1px solid ' + TOK.hairline,
                borderRadius: 6,
                overflow: 'hidden',
                background: isInternal ? TOK.ecru : TOK.paper,
                borderLeft: isInternal ? '3px solid ' + TOK.slate : '1px solid ' + TOK.hairline
              }}>
                <div
                  role="button" tabIndex={0} aria-expanded={!!open}
                  className="focusable"
                  onClick={() => toggleCluster(name)}
                  onKeyDown={(e) => clusterKey(e, name)}
                  style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 14px', cursor: 'pointer' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    {isInternal && <Icon name="Lock" size={13} color={TOK.slate} />}
                    <span style={{ fontFamily: FONT.body, fontWeight: 600, fontSize: 13.5, color: TOK.ink }}>{name}</span>
                    <span className="data" style={{ fontSize: 10.5, padding: '2px 7px', borderRadius: 999, background: TOK.panel, color: TOK.secondary }}>{items.length}</span>
                  </div>
                  <Icon name={open ? 'Minus' : 'Plus'} size={15} color={TOK.grey} />
                </div>

                {open && (
                  <div style={{ borderTop: '1px solid ' + TOK.hairline }}>
                    {items.map(ev => {
                      const dm = dirMeta[ev.signal_direction] || dirMeta.supporting;
                      const src = state.sources.find(s => s.id === ev.source_id);
                      return (
                        <div
                          key={ev.id}
                          role="button" tabIndex={0}
                          className="focusable"
                          onClick={() => dispatch({ type: 'OPEN_PROVENANCE', ev })}
                          onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); dispatch({ type: 'OPEN_PROVENANCE', ev }); } }}
                          style={{ padding: '13px 14px', borderTop: items.indexOf(ev) ? '1px solid ' + TOK.hairline : 'none', cursor: 'pointer' }}>
                          <p className="bodytx" style={{ fontSize: 13, color: TOK.ink, marginBottom: 8 }}>“{truncate(ev.pull_quote, 80)}”</p>
                          {/* relevance bar */}
                          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 6 }}>
                            <div style={{ flex: 1, height: 6, borderRadius: 999, background: TOK.panel, overflow: 'hidden' }}>
                              <div style={{ height: '100%', borderRadius: 999, background: TOK.cyan, width: (ev.relevance_score * 100) + '%', animation: 'barFill .6s cubic-bezier(.4,0,.2,1) both' }} />
                            </div>
                            <span className="data" style={{ fontSize: 10.5, color: TOK.secondary, width: 34, textAlign: 'right' }}>{ev.relevance_score.toFixed(2)}</span>
                          </div>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                            <span className="data" style={{ fontSize: 10.5, padding: '2px 7px', borderRadius: 999, border: '1px solid ' + TOK.hairline, color: TOK.grey }}>{ev.recency_days}d</span>
                            <span className="data" style={{ fontSize: 10.5, padding: '2px 7px', borderRadius: 999, border: '1px solid ' + dm.col, color: dm.col }}>{dm.gl} {dm.lbl}</span>
                            {src && <span className="lbl" style={{ color: TOK.muted }}>{src.publisher}</span>}
                            <span style={{ flex: 1 }} />
                            <span className="data" style={{ fontSize: 10, color: TOK.cyan }}>Trace source ›</span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          })}

          {!loading && clusters.length === 0 && (
            <div style={{ textAlign: 'center', padding: '32px 0' }}>
              <Icon name="Inbox" size={28} color={TOK.muted} />
              <div className="bodytx" style={{ fontSize: 13, color: TOK.secondary, marginTop: 8 }}>No linked evidence for this recommendation.</div>
            </div>
          )}

          {/* action row (p-hitl) */}
          {!loading && (
            <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginTop: 18, paddingTop: 18, borderTop: '1px solid ' + TOK.hairline }}>
              <button
                className="btn btn-pri focusable"
                onClick={() => dispatch({ type: 'ADD_EXPORT', id: rec.id })}
                disabled={state.exportDraft.includes(rec.id)}>
                <Icon name="FilePlus" size={15} />
                {state.exportDraft.includes(rec.id) ? 'In export draft' : 'Add to export'}
              </button>
              <button className="btn focusable" onClick={onFlag}>
                <Icon name="Flag" size={15} /> Flag for review
              </button>
              {sentEv && (
                <button className="btn-link focusable" style={{ cursor: 'pointer' }}
                  onClick={() => dispatch({ type: 'SELECT_THEME', theme: state.sentiment.find(s => true) ? (state.sentiment.find(s => s.theme.toLowerCase().includes(rec.theme.split(' ')[0].toLowerCase()))?.theme || state.selectedTheme) : state.selectedTheme })}>
                  <Icon name="TrendingUp" size={15} /> Sentiment trend
                </button>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// PATTERN MANIFEST: p-doc-outline, p-quote-pull, p-trans, proto/Spinner, proto/Skeleton, proto/Empty, proto/Toast, proto/Alert, proto/Stat
function Screen_source_provenance_view({ state, dispatch }) {
  const ev = state.selectedEvidence;
  const source = ev ? state.sources.find(s => s.id === ev.source_id) : null;
  const [copied, setCopied] = useState(false);
  const [dialReveal, setDialReveal] = useState(false);
  const aiStatus = state.aiStatus['citation_generation'];

  useEffect(() => {
    callAI('citation_generation', dispatch);
    const t = setTimeout(() => setDialReveal(true), 60);
    return () => clearTimeout(t);
  }, []);

  if (!ev) {
    return (
      <div style={{ padding: 40, maxWidth: 600, margin: '0 auto' }}>
        <div className="cardbox cascade" style={{ padding: '32px 28px', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12 }}>
          <Icon name="Search" size={30} color={TOK.muted} />
          <div className="disp" style={{ fontSize: 18, color: TOK.ink }}>No passage located</div>
          <div className="bodytx" style={{ fontSize: 13, color: TOK.secondary, textAlign: 'center' }}>Select an evidence item from a recommendation to trace its source passage.</div>
          <button className="btn btn-pri focusable" onClick={() => dispatch({ type: 'NAV', screen: 'recommendation_evidence_panel' })}>Return to evidence panel</button>
        </div>
      </div>
    );
  }

  const isInternal = source && source.type === 'internal';
  const loading = aiStatus && aiStatus.state === 'loading';
  const error = aiStatus && aiStatus.state === 'error';

  // build the faux document passage with the cited quote highlighted
  const lead = 'In the broader market context, analysts have tracked shifting dynamics across the segment. ';
  const trail = ' These findings inform the recommendation\'s evidentiary basis and were synthesized into the 2026 outlook brief alongside corroborating signals.';

  const typeLabel = source ? source.type.replace(/_/g, ' ') : ev.type.replace(/_/g, ' ');
  const citationStr = source
    ? `${source.publisher} (${source.publish_date.split('-')[0]}). ${source.title}. ${typeLabel.charAt(0).toUpperCase() + typeLabel.slice(1)}. q-weight ${source.quality_weight.toFixed(2)}.`
    : `${ev.type} evidence · relevance ${ev.relevance_score.toFixed(2)}.`;

  const handleCopy = () => {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(citationStr).catch(() => {});
    }
    dispatch({ type: 'TOAST', msg: 'Citation copied' });
    setCopied(true);
    setTimeout(() => setCopied(false), 1400);
  };

  // quality dial geometry
  const qw = source ? source.quality_weight : ev.relevance_score;
  const dSize = 96, dR = 38, dC = 2 * Math.PI * dR;
  const dCol = qw >= 0.8 ? TOK.success : qw >= 0.65 ? TOK.cyan : qw >= 0.5 ? TOK.warn : TOK.error;

  const dirCol = { supporting: TOK.success, contradicting: TOK.error, constraining: TOK.warn }[ev.signal_direction] || TOK.grey;

  return (
    <div style={{ padding: '28px 40px 60px', maxWidth: 1180, margin: '0 auto' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 18 }}>
        <button className="btn-link focusable" onClick={() => dispatch({ type: 'NAV', screen: 'recommendation_evidence_panel' })} style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
          <Icon name="ArrowLeft" size={15} />Return to evidence panel
        </button>
        <div className="kicker">Source Provenance</div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1.6fr 1fr', gap: 24 }}>
        {/* MAIN: document-context viewer */}
        <div className="cardbox cascade" style={{ padding: 0, overflow: 'hidden' }}>
          <div style={{ padding: '14px 22px', background: TOK.panel, borderBottom: '1px solid ' + TOK.hairline, display: 'flex', alignItems: 'center', gap: 10 }}>
            <Icon name="FileText" size={16} color={TOK.secondary} />
            <span className="data" style={{ fontSize: 12, color: TOK.ink }}>{source ? source.title : 'Evidence passage'}</span>
            <div style={{ flex: 1 }} />
            <span className="data" style={{ fontSize: 10.5, padding: '3px 8px', borderRadius: 999, border: '1px solid ' + dirCol, color: dirCol }}>{ev.signal_direction}</span>
          </div>

          <div style={{ padding: '28px 30px' }}>
            {loading ? (
              <div aria-busy="true">
                <div className="shimmer" style={{ height: 14, width: '55%', borderRadius: 4, marginBottom: 12 }} />
                <div className="shimmer" style={{ height: 11, width: '100%', borderRadius: 4, marginBottom: 9 }} />
                <div className="shimmer" style={{ height: 11, width: '88%', borderRadius: 4, marginBottom: 9 }} />
                <div className="shimmer" style={{ height: 11, width: '94%', borderRadius: 4, marginBottom: 20 }} />
                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8 }} role="status" aria-label="Loading">
                  <Icon name="Loader" size={26} color={TOK.accent} />
                  <span className="lbl">Locating cited passage…</span>
                </div>
              </div>
            ) : (
              <>
                <div className="lbl" style={{ marginBottom: 14 }}>Cited passage · in situ</div>
                <p className="bodytx" style={{ fontSize: 15.5, lineHeight: 1.7, color: TOK.muted }}>
                  <span>{lead}</span>
                  <span style={{
                    background: TOK.washWarn,
                    color: TOK.ink,
                    padding: '2px 4px',
                    borderRadius: 2,
                    fontWeight: 500,
                    boxShadow: 'inset 0 -2px 0 ' + TOK.rust,
                    animation: 'ambPulse 1.4s ease-in-out 1'
                  }}>{ev.pull_quote}</span>
                  <span>{trail}</span>
                </p>

                <div style={{ marginTop: 26, padding: '12px 14px', background: TOK.pale, border: '1px solid ' + TOK.hairline, borderRadius: 2, display: 'flex', gap: 10, alignItems: 'flex-start' }}>
                  <Icon name="Link2" size={15} color={TOK.cyan} />
                  <div>
                    <div className="data" style={{ fontSize: 10.5, color: TOK.cyan, letterSpacing: 1, textTransform: 'uppercase' }}>Provenance footnote</div>
                    <div className="bodytx" style={{ fontSize: 12.5, color: TOK.secondary, marginTop: 3 }}>
                      This passage links back to its source record and is preserved as an embedded citation when exported to PPTX, PDF, or Notion — the link survives export.
                    </div>
                  </div>
                </div>

                <div style={{ marginTop: 12, padding: '10px 14px', background: TOK.washCool, border: '1px solid ' + TOK.hairline, borderLeft: '3px solid ' + TOK.cyan, borderRadius: 2, display: 'flex', gap: 9, alignItems: 'flex-start' }}>
                  <Icon name="ShieldCheck" size={14} color={TOK.cyan} />
                  <div className="bodytx" style={{ fontSize: 12, color: TOK.secondary }}>
                    Stale-link guard: source last verified at refresh <b style={{ color: TOK.ink }}>{state.lastRefresh}</b>. If the upstream document changes, this provenance link is re-validated on the next data refresh.
                  </div>
                </div>
              </>
            )}
          </div>
        </div>

        {/* SIDEBAR */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 18 }}>
          {isInternal && (
            <div role="status" className="cascade" style={{ background: TOK.surface, border: '1px solid ' + TOK.warn, borderLeft: '3px solid ' + TOK.warn, borderRadius: 6, padding: '11px 13px', display: 'flex', gap: 9, alignItems: 'flex-start' }}>
              <Icon name="AlertTriangle" size={15} color={TOK.warn} />
              <div>
                <div className="data" style={{ fontSize: 11.5, fontWeight: 600, color: TOK.warn }}>Internal annotation</div>
                <div className="bodytx" style={{ fontSize: 12, color: TOK.secondary, marginTop: 2 }}>This is an internal note, not externally sourced evidence. Treat as context, not corroboration.</div>
              </div>
            </div>
          )}

          {/* metadata rows */}
          <div className="cardbox cascade" style={{ padding: '18px 20px', animationDelay: '.05s' }}>
            <div className="lbl" style={{ marginBottom: 12 }}>Source metadata</div>
            {source ? (
              [['Publisher', source.publisher], ['Published', source.publish_date], ['Type', typeLabel], ['Methodology', source.methodology_note]].map(([k, v], i) => (
                <div key={k} style={{ display: 'flex', flexDirection: 'column', gap: 3, padding: '9px 0', borderTop: i === 0 ? 'none' : '1px solid ' + TOK.hairline }}>
                  <span className="lbl" style={{ fontSize: 10 }}>{k}</span>
                  <span className="bodytx" style={{ fontSize: 13, color: TOK.ink }}>{v}</span>
                </div>
              ))
            ) : (
              <div className="bodytx" style={{ fontSize: 12.5, color: TOK.secondary }}>No source record attached to this evidence item.</div>
            )}
          </div>

          {/* quality-weight dial */}
          <div className="cardbox cascade" style={{ padding: '18px 20px', animationDelay: '.1s', display: 'flex', alignItems: 'center', gap: 18 }}>
            <svg width={dSize} height={dSize} role="img" aria-label={'Quality weight ' + qw.toFixed(2)}>
              <circle cx={dSize / 2} cy={dSize / 2} r={dR} fill="none" stroke={TOK.ecru} strokeWidth={7} />
              <circle cx={dSize / 2} cy={dSize / 2} r={dR} fill="none" stroke={dCol} strokeWidth={7} strokeLinecap="round"
                strokeDasharray={(dC * (dialReveal ? qw : 0)) + ' ' + dC} transform={'rotate(-90 ' + dSize / 2 + ' ' + dSize / 2 + ')'}
                style={{ transition: 'stroke-dasharray .35s cubic-bezier(.4,0,.2,1)' }} />
              <text x={dSize / 2} y={dSize / 2 + 6} textAnchor="middle" style={{ font: '600 20px ' + FONT.mono, fill: TOK.ink }}>{qw.toFixed(2)}</text>
            </svg>
            <div>
              <div className="lbl" style={{ fontSize: 10, marginBottom: 4 }}>Quality weight</div>
              <div className="bodytx" style={{ fontSize: 12, color: TOK.secondary }}>{source ? 'Source reliability score used to weight this evidence in confidence scoring.' : 'Relevance score for this evidence item.'}</div>
            </div>
          </div>

          {/* citation block */}
          <div className="cardbox cascade" style={{ padding: '18px 20px', animationDelay: '.15s' }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
              <span className="lbl">Board-grade citation</span>
              <AIProvenance status={aiStatus} />
            </div>

            {error ? (
              <div role="alert" style={{ background: TOK.surface, border: '1px solid ' + TOK.error, borderLeft: '3px solid ' + TOK.error, borderRadius: 6, padding: '12px 13px' }}>
                <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 6 }}>
                  <Icon name="XCircle" size={15} color={TOK.error} />
                  <span className="data" style={{ fontSize: 12.5, fontWeight: 600, color: TOK.error }}>Citation could not be generated</span>
                </div>
                <div className="bodytx" style={{ fontSize: 12, color: TOK.secondary, marginBottom: 10 }}>The primary provider failed; a fallback provider can be retried.</div>
                <button className="btn focusable" onClick={() => callAI('citation_generation', dispatch)}><Icon name="RefreshCw" size={14} />Retry</button>
              </div>
            ) : (
              <>
                <div className="data" style={{ fontSize: 12.5, lineHeight: 1.6, color: TOK.ink, background: TOK.pale, border: '1px solid ' + TOK.hairline, borderRadius: 2, padding: '12px 14px', marginBottom: 12 }}>
                  {citationStr}
                </div>
                <button className="btn btn-pri focusable" style={{ width: '100%', justifyContent: 'center' }} onClick={handleCopy} aria-label="Copy citation to clipboard">
                  <Icon name={copied ? 'Check' : 'Copy'} size={15} />{copied ? 'Copied' : 'Copy citation'}
                </button>
                <div className="bodytx" style={{ fontSize: 11, color: TOK.muted, marginTop: 10, lineHeight: 1.5 }}>
                  Copy uses the keyboard-accessible clipboard API and preserves formatting across PPTX / PDF / Notion exports.
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// PATTERN MANIFEST: p-chart, p-time-machine, p-facet
function Screen_sentiment_trend_explorer({ state, dispatch }) {
  const prefersReduced = useMemo(()=> window.matchMedia && window.matchMedia('(prefers-reduced-motion:reduce)').matches, []);
  const themes = useMemo(()=> Array.from(new Set(state.sentiment.map(s=>s.theme))), [state.sentiment]);
  const series = useMemo(()=> state.sentiment.filter(s=>s.theme===state.selectedTheme), [state.sentiment, state.selectedTheme]);
  const availSegments = useMemo(()=> series.map(s=>s.segment), [series]);
  const [activeSeg, setActiveSeg] = useState(null);
  const [hoverPin, setHoverPin] = useState(null);
  const [animKey, setAnimKey] = useState(0);
  const aiFlow = state.aiStatus['sentiment_shift_detection'];
  const loading = aiFlow && aiFlow.state==='loading';

  useEffect(()=>{ callAI('sentiment_shift_detection', dispatch); }, []);
  useEffect(()=>{ setActiveSeg(null); setHoverPin(null); setAnimKey(k=>k+1); }, [state.selectedTheme]);

  const visible = useMemo(()=>{
    if(activeSeg==null) return series;
    return series.filter(s=>s.segment===activeSeg);
  }, [series, activeSeg]);

  const SEG_COLORS = { Consumers: TOK.cyan, Brokers: TOK.teal, Press: TOK.rust };
  const segColor = (seg)=> SEG_COLORS[seg] || TOK.slate;

  // chart geometry
  const W=760, H=320, padL=46, padR=24, padT=24, padB=40;
  const plotW = W-padL-padR, plotH = H-padT-padB;
  const N=24;
  const xAt = (i)=> padL + (plotW * i/(N-1));
  const yAt = (v)=> padT + plotH * (1 - (v+1)/2); // v in -1..1
  const baseline = yAt(0);

  const pathFor = (vals)=> vals.map((v,i)=> (i===0?'M':'L')+xAt(i).toFixed(1)+' '+yAt(v).toFixed(1)).join(' ');
  const pathLen = plotW * 1.4;

  const allPins = useMemo(()=>{
    const out=[];
    visible.forEach(s=>{
      (s.inflection_points||[]).forEach(p=>{
        out.push({ seg:s.segment, month:p.month, label:p.label, x:xAt(p.month), y:yAt(s.monthly_values[p.month]), color:segColor(s.segment) });
      });
    });
    return out;
  }, [visible]);

  const fmtSigned = (n)=> (n>=0?'+':'')+n.toFixed(2);
  const netColor = (n)=> n>0?TOK.success : n<0?TOK.error : TOK.grey;

  return (
    <div style={{padding:'28px 40px',maxWidth:1180,margin:'0 auto'}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',marginBottom:18}}>
        <div>
          <div className="kicker" style={{marginBottom:6}}>Sentiment Trend Explorer</div>
          <div className="disp" style={{fontSize:30,color:TOK.ink}}>Attitudinal movement · 24 months</div>
        </div>
        <button className="btn-link focusable" onClick={()=>dispatch({type:'NAV',screen:'recommendation_evidence_panel'})}>
          <Icon name="ArrowLeft" size={14}/> Return to evidence panel
        </button>
      </div>

      {/* theme picker + AI provenance */}
      <div style={{display:'flex',alignItems:'center',gap:14,marginBottom:18,flexWrap:'wrap'}}>
        <span className="lbl">Theme</span>
        <div style={{position:'relative'}}>
          <select className="data focusable" value={state.selectedTheme}
            onChange={(e)=>dispatch({type:'SELECT_THEME',theme:e.target.value})}
            style={{fontSize:13,padding:'9px 34px 9px 12px',border:'1px solid '+TOK.hairline,borderRadius:2,background:TOK.paper,color:TOK.ink,appearance:'none',cursor:'pointer',minWidth:300}}>
            {themes.map(t=> <option key={t} value={t}>{t}</option>)}
          </select>
          <span style={{position:'absolute',right:10,top:'50%',transform:'translateY(-50%)',pointerEvents:'none',color:TOK.grey}}><Icon name="ChevronDown" size={15}/></span>
        </div>
        <div style={{flex:1}}/>
        <AIProvenance status={aiFlow}/>
      </div>

      {series.length===0 ? (
        <div className="cardbox cascade" style={{padding:'60px 40px',textAlign:'center'}}>
          <Icon name="Inbox" size={32} color={TOK.muted}/>
          <div className="disp" style={{fontSize:20,marginTop:14,color:TOK.ink}}>No sentiment series for this theme</div>
          <div className="bodytx" style={{marginTop:6,color:TOK.secondary}}>The corpus has no signal for “{state.selectedTheme}”.</div>
        </div>
      ) : (
      <div style={{display:'grid',gridTemplateColumns:'1fr 280px',gap:20,alignItems:'start'}}>
        {/* chart card */}
        <div className="cardbox cascade" style={{padding:18}}>
          {/* segment facet toggle */}
          <div style={{display:'flex',gap:8,marginBottom:14,flexWrap:'wrap',alignItems:'center'}}>
            <span className="lbl" style={{marginRight:4}}>Segment</span>
            <button className="navchip focusable" aria-pressed={activeSeg==null}
              onClick={()=>setActiveSeg(null)}
              style={activeSeg==null?{borderColor:TOK.hairline,background:TOK.panel,color:TOK.ink}:{}}>All</button>
            {availSegments.map(seg=>(
              <button key={seg} className="navchip focusable" aria-pressed={activeSeg===seg}
                onClick={()=>setActiveSeg(activeSeg===seg?null:seg)}
                style={activeSeg===seg?{borderColor:segColor(seg),background:TOK.paper,color:TOK.ink}:{}}>
                <span style={{display:'inline-block',width:8,height:8,borderRadius:999,background:segColor(seg),marginRight:6,verticalAlign:'middle'}}/>
                {seg}
              </button>
            ))}
          </div>

          <div style={{position:'relative'}}>
            {loading && (
              <div className="shimmer" style={{position:'absolute',inset:0,borderRadius:4,zIndex:5}} aria-hidden="true"/>
            )}
            <svg key={animKey} viewBox={'0 0 '+W+' '+H} width="100%" role="img"
              aria-label={'Sentiment line chart for '+state.selectedTheme+', '+visible.map(s=>s.segment).join(', ')+' over 24 months'}
              style={{display:'block',opacity:loading?0.2:1,transition:'opacity .3s'}}>
              {/* y gridlines */}
              {[-1,-0.5,0,0.5,1].map(v=>(
                <g key={v}>
                  <line x1={padL} x2={W-padR} y1={yAt(v)} y2={yAt(v)} stroke={v===0?TOK.ruleMid:TOK.hairline} strokeWidth={v===0?1.5:1} strokeDasharray={v===0?'':'3 3'}/>
                  <text x={padL-8} y={yAt(v)+4} textAnchor="end" fontFamily={FONT.mono} fontSize="10" fill={TOK.grey}>{v>0?'+':''}{v.toFixed(1)}</text>
                </g>
              ))}
              {/* x month ticks */}
              {[0,6,12,18,23].map(i=>(
                <text key={i} x={xAt(i)} y={H-padB+18} textAnchor="middle" fontFamily={FONT.mono} fontSize="10" fill={TOK.grey}>M{i+1}</text>
              ))}
              {/* series lines */}
              {visible.map(s=>{
                const d=pathFor(s.monthly_values);
                return (
                  <path key={s.id} d={d} fill="none" stroke={segColor(s.segment)} strokeWidth={2.2} strokeLinecap="round" strokeLinejoin="round"
                    style={prefersReduced?{}:{strokeDasharray:pathLen, strokeDashoffset:pathLen, '--len':pathLen, animation:'drawLine .8s cubic-bezier(.4,0,.2,1) forwards'}}/>
                );
              })}
              {/* inflection pins */}
              {allPins.map((p,i)=>{
                const key=p.seg+'-'+p.month+'-'+i;
                const showLabel = hoverPin===key;
                return (
                  <g key={key} tabIndex={0} className="focusable"
                    role="img" aria-label={'Inflection at month '+(p.month+1)+' for '+p.seg+': '+p.label}
                    onMouseEnter={()=>setHoverPin(key)} onMouseLeave={()=>setHoverPin(null)}
                    onFocus={()=>setHoverPin(key)} onBlur={()=>setHoverPin(null)}
                    style={{cursor:'pointer'}}>
                    <line x1={p.x} x2={p.x} y1={p.y} y2={p.y-22} stroke={p.color} strokeWidth={1} strokeDasharray="2 2"/>
                    <circle cx={p.x} cy={p.y-22} r={5} fill={TOK.paper} stroke={p.color} strokeWidth={2}/>
                    <circle cx={p.x} cy={p.y} r={3.5} fill={p.color}/>
                    {showLabel && (()=>{
                      const tw = Math.min(220, 18 + p.label.length*5.4);
                      const lx = Math.max(padL, Math.min(W-padR-tw, p.x-tw/2));
                      const ly = Math.max(2, p.y-58);
                      return (
                        <g>
                          <rect x={lx} y={ly} width={tw} height={36} rx={3} fill={TOK.rail}/>
                          <text x={lx+9} y={ly+15} fontFamily={FONT.mono} fontSize="9" fill={p.color}>M{p.month+1} · {p.seg}</text>
                          <text x={lx+9} y={ly+28} fontFamily={FONT.body} fontSize="10.5" fill={TOK.paper}>{p.label.length>34?p.label.slice(0,32)+'…':p.label}</text>
                        </g>
                      );
                    })()}
                  </g>
                );
              })}
            </svg>
          </div>

          {/* legend */}
          <div style={{display:'flex',gap:18,marginTop:8,flexWrap:'wrap'}}>
            {series.map(s=>(
              <span key={s.id} className="data" style={{fontSize:11,color:visible.includes(s)?TOK.ink:TOK.muted,display:'inline-flex',alignItems:'center',gap:6}}>
                <span style={{display:'inline-block',width:14,height:3,background:visible.includes(s)?segColor(s.segment):TOK.hairline}}/>
                {s.segment}
              </span>
            ))}
            <span className="data" style={{fontSize:10.5,color:TOK.grey,marginLeft:'auto'}}>◇ pins = significant inflections</span>
          </div>
        </div>

        {/* readout panel */}
        <div style={{display:'flex',flexDirection:'column',gap:14}}>
          {visible.map(s=>(
            <div key={s.id} className="cardbox cascade" style={{padding:16,borderLeft:'3px solid '+segColor(s.segment)}}>
              <div className="lbl" style={{color:segColor(s.segment),marginBottom:10}}>{s.segment}</div>
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline',marginBottom:10}}>
                <span className="lbl">Net change</span>
                <span className="data" style={{fontSize:22,fontWeight:600,color:netColor(s.net_change)}}>{fmtSigned(s.net_change)}</span>
              </div>
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline'}}>
                <span className="lbl">Current score</span>
                <span className="data" style={{fontSize:18,color:TOK.ink}}>{fmtSigned(s.current_score)}</span>
              </div>
              <div style={{marginTop:10,paddingTop:10,borderTop:'1px solid '+TOK.hairline}}>
                <span className="data" style={{fontSize:10.5,color:TOK.grey}}>{(s.inflection_points||[]).length} labeled inflection{(s.inflection_points||[]).length===1?'':'s'}</span>
              </div>
            </div>
          ))}
        </div>
      </div>
      )}
    </div>
  );
}

// PATTERN MANIFEST: p-compare, p-portfolio-mix, p-facet, p-kpi

function Screen_theme_comparison_grid({ state, dispatch }) {
  const TOK = {
    rail:'#0D0D0D', ink:'#141414', accent:'#B8B800', cyan:'#00B7C3', rust:'#CC6644',
    teal:'#115054', success:'#0CCE6B', error:'#FF5A5A', paper:'#FFFFFF', ecru:'#F2F1EA',
    grey:'#73757A', hairline:'#DDDDD6', warn:'#CC6644', washWarn:'#FAF1EC',
    panel:'#F5F5F0', secondary:'#666666', muted:'#999999', bg:'#FAFAF7'
  };
  const FONT = { display:"'Saira Condensed',sans-serif", body:"'Archivo',sans-serif", mono:"'IBM Plex Mono',monospace" };

  const [sortBy, setSortBy] = useState('confidence');
  const [themeFilter, setThemeFilter] = useState('all');
  const [hover, setHover] = useState(null);

  useEffect(()=>{ callAI('confidence_coverage_scoring', dispatch); },[]);

  const themes = useMemo(()=>{
    const s=new Set(state.recommendations.map(r=>r.theme)); return ['all',...Array.from(s)];
  },[state.recommendations]);

  const recs = useMemo(()=>{
    let r = state.recommendations.filter(x=>themeFilter==='all'||x.theme===themeFilter);
    const sorters = {
      confidence:(a,b)=>b.confidence_score-a.confidence_score,
      impact:(a,b)=>b.impact_score-a.impact_score,
      evidence:(a,b)=>b.evidence_count-a.evidence_count
    };
    return [...r].sort(sorters[sortBy]);
  },[state.recommendations, themeFilter, sortBy]);

  // matrix geometry
  const W=620, H=440, padL=58, padR=30, padT=24, padB=52;
  const ix=[0.4,0.95], iy=[3,9];
  const xs = c => padL + (c-ix[0])/(ix[1]-ix[0])*(W-padL-padR);
  const ys = i => H-padB - (i-iy[0])/(iy[1]-iy[0])*(H-padT-padB);
  const rad = ec => 9 + (ec-4)/(11-4)*16; // 9..25

  const bandColor = s => s>=0.8?TOK.success:s>=0.65?TOK.cyan:s>=0.5?TOK.warn:TOK.error;
  const bandLabel = s => s>=0.8?'Well-supported':s>=0.65?'Supported':s>=0.5?'Emerging':'Speculative';

  const xTicks=[0.4,0.55,0.7,0.85,0.95];
  const yTicks=[3,5,7,9];

  const sortOpts=[['confidence','Confidence'],['impact','Impact'],['evidence','Evidence coverage']];

  return (
    <div style={{padding:'28px 40px 64px',maxWidth:1240,margin:'0 auto'}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-end',marginBottom:6}}>
        <div>
          <div className="kicker">Defensibility Matrix</div>
          <h1 className="disp" style={{fontSize:32,color:TOK.ink,marginTop:4}}>Theme Comparison Grid</h1>
        </div>
        <AIProvenance status={state.aiStatus['confidence_coverage_scoring']}/>
      </div>
      <p className="bodytx" style={{maxWidth:680,marginBottom:20}}>
        Confidence × impact, bubbles sized by evidence coverage. Contested themes carry a dashed rust outline.
        Sort to re-rank priority and watch bubbles drift to new coordinates.
      </p>

      {/* FACET CONTROLS (p-facet) */}
      <div style={{display:'flex',gap:24,flexWrap:'wrap',marginBottom:20,alignItems:'flex-end'}}>
        <div>
          <div className="lbl" style={{marginBottom:7}}>Sort by</div>
          <div style={{display:'flex',gap:6}}>
            {sortOpts.map(([id,lbl])=>(
              <button key={id} className="navchip focusable" aria-pressed={sortBy===id}
                onClick={()=>setSortBy(id)}
                style={{background:sortBy===id?TOK.panel:TOK.paper,border:'1.5px solid '+(sortBy===id?TOK.accent:TOK.hairline),color:sortBy===id?TOK.ink:TOK.muted,borderRadius:999}}>
                {lbl}
              </button>
            ))}
          </div>
        </div>
        <div>
          <div className="lbl" style={{marginBottom:7}}>Theme filter</div>
          <div style={{display:'flex',gap:6,flexWrap:'wrap',maxWidth:560}}>
            {themes.map(t=>(
              <button key={t} className="navchip focusable" aria-pressed={themeFilter===t}
                onClick={()=>setThemeFilter(t)}
                style={{background:themeFilter===t?TOK.panel:TOK.paper,border:'1.5px solid '+(themeFilter===t?TOK.accent:TOK.hairline),color:themeFilter===t?TOK.ink:TOK.muted,borderRadius:999}}>
                {t==='all'?'All themes':t}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div style={{display:'grid',gridTemplateColumns:'1fr 320px',gap:24,alignItems:'start'}}>
        {/* MATRIX (p-portfolio-mix) */}
        <div className="cardbox" style={{padding:18}}>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:6}}>
            <div className="lbl">Confidence × Impact scatter</div>
            <div style={{display:'flex',gap:14,flexWrap:'wrap'}}>
              {[['Well-supported',TOK.success],['Supported',TOK.cyan],['Emerging',TOK.warn],['Speculative',TOK.error]].map(([l,c])=>(
                <span key={l} className="data" style={{fontSize:10,color:TOK.secondary,display:'inline-flex',alignItems:'center',gap:5}}>
                  <span style={{width:9,height:9,borderRadius:999,background:c,display:'inline-block'}}/>{l}
                </span>
              ))}
            </div>
          </div>

          <div style={{position:'relative'}}>
            <svg width="100%" viewBox={'0 0 '+W+' '+H} role="img" aria-label="Confidence by impact scatter matrix">
              {/* grid */}
              {xTicks.map(t=>(<line key={'gx'+t} x1={xs(t)} x2={xs(t)} y1={padT} y2={H-padB} stroke={TOK.ecru} strokeWidth={1}/>))}
              {yTicks.map(t=>(<line key={'gy'+t} x1={padL} x2={W-padR} y1={ys(t)} y2={ys(t)} stroke={TOK.ecru} strokeWidth={1}/>))}
              {/* axes */}
              <line x1={padL} x2={W-padR} y1={H-padB} y2={H-padB} stroke={TOK.hairline} strokeWidth={1.5}/>
              <line x1={padL} x2={padL} y1={padT} y2={H-padB} stroke={TOK.hairline} strokeWidth={1.5}/>
              {xTicks.map(t=>(
                <text key={'xt'+t} x={xs(t)} y={H-padB+18} textAnchor="middle" style={{fontFamily:FONT.mono,fontSize:10,fill:TOK.grey}}>{t.toFixed(2)}</text>
              ))}
              {yTicks.map(t=>(
                <text key={'yt'+t} x={padL-10} y={ys(t)+3} textAnchor="end" style={{fontFamily:FONT.mono,fontSize:10,fill:TOK.grey}}>{t}</text>
              ))}
              <text x={(padL+W-padR)/2} y={H-8} textAnchor="middle" style={{fontFamily:FONT.mono,fontSize:10,letterSpacing:2,fill:TOK.grey}}>CONFIDENCE →</text>
              <text x={14} y={(padT+H-padB)/2} textAnchor="middle" transform={'rotate(-90 14 '+(padT+H-padB)/2+')'} style={{fontFamily:FONT.mono,fontSize:10,letterSpacing:2,fill:TOK.grey}}>IMPACT →</text>

              {/* bubbles */}
              {recs.map(r=>{
                const cx=xs(r.confidence_score), cy=ys(r.impact_score), rr=rad(r.evidence_count);
                const col=bandColor(r.confidence_score);
                const hov=hover===r.id;
                return (
                  <g key={r.id}>
                    <circle cx={cx} cy={cy} r={rr} fill={col} fillOpacity={r.contested?0.18:0.55}
                      stroke={r.contested?TOK.rust:col} strokeWidth={r.contested?2:1.5}
                      strokeDasharray={r.contested?'4 3':'none'}
                      style={{transition:'cx .4s cubic-bezier(.4,0,.2,1),cy .4s cubic-bezier(.4,0,.2,1)',cursor:'pointer'}}
                      onMouseEnter={()=>setHover(r.id)} onMouseLeave={()=>setHover(null)}
                      onClick={()=>dispatch({type:'SELECT_REC',id:r.id})}/>
                    {r.contested && <text x={cx} y={cy+4} textAnchor="middle" style={{fontFamily:FONT.mono,fontSize:11,fill:TOK.rust,pointerEvents:'none'}}>!</text>}
                    {hov && (
                      <g pointerEvents="none">
                        <rect x={Math.min(cx+10,W-210)} y={cy-58} width={200} height={52} rx={3} fill={TOK.rail}/>
                        <text x={Math.min(cx+10,W-210)+10} y={cy-40} style={{fontFamily:FONT.body,fontSize:11,fontWeight:600,fill:TOK.paper}}>{r.title.slice(0,30)}{r.title.length>30?'…':''}</text>
                        <text x={Math.min(cx+10,W-210)+10} y={cy-25} style={{fontFamily:FONT.mono,fontSize:10,fill:'#C9D0DB'}}>conf {r.confidence_score.toFixed(2)} · {r.evidence_count} ev · {r.coverage_status}</text>
                        <text x={Math.min(cx+10,W-210)+10} y={cy-11} style={{fontFamily:FONT.mono,fontSize:9,fill:col}}>{bandLabel(r.confidence_score)}</text>
                      </g>
                    )}
                  </g>
                );
              })}
            </svg>
          </div>
          <div className="data" style={{fontSize:10,color:TOK.muted,marginTop:6}}>Bubble size ∝ evidence count · dashed rust outline + ! = contested</div>

          {/* focusable list alternative for non-pointer */}
          <div role="list" aria-label="Recommendations as accessible list" style={{marginTop:14,borderTop:'1px solid '+TOK.hairline,paddingTop:12,display:'flex',flexWrap:'wrap',gap:6}}>
            {recs.map(r=>(
              <button key={r.id} role="listitem" className="focusable"
                onClick={()=>dispatch({type:'SELECT_REC',id:r.id})}
                style={{fontFamily:FONT.mono,fontSize:10,padding:'4px 8px',borderRadius:2,border:'1px solid '+TOK.hairline,background:TOK.paper,color:TOK.secondary,cursor:'pointer',display:'inline-flex',alignItems:'center',gap:4}}>
                <span style={{width:8,height:8,borderRadius:999,background:bandColor(r.confidence_score)}}/>
                {r.title.slice(0,22)}… ↗
              </button>
            ))}
          </div>
        </div>

        {/* PRIORITY SIDEBAR (p-compare / p-kpi) */}
        <div className="cardbox" style={{padding:0,overflow:'hidden'}}>
          <div style={{padding:'14px 16px',borderBottom:'1px solid '+TOK.hairline,background:TOK.panel}}>
            <div className="lbl">Priority — by {sortOpts.find(o=>o[0]===sortBy)[1]}</div>
            <div className="data" style={{fontSize:10,color:TOK.muted,marginTop:3}}>{recs.length} themes · reorders on sort</div>
          </div>
          <div>
            {recs.map((r,i)=>{
              const lowCov = r.coverage_status==='thin' || r.evidence_count<=5;
              const flagged = state.flags.some(f=>f.recommendation_id===r.id && f.status==='open');
              return (
                <div key={r.id} className="cascade" style={{padding:'12px 16px',borderTop:i>0?'1px solid '+TOK.hairline:'none',animationDelay:(i*0.04)+'s'}}>
                  <div style={{display:'flex',gap:10,alignItems:'flex-start'}}>
                    <div className="data" style={{fontSize:14,color:TOK.muted,width:18,paddingTop:2}}>{i+1}</div>
                    <ConfRing score={r.confidence_score} size={38}/>
                    <div style={{flex:1,minWidth:0}}>
                      <button className="focusable" onClick={()=>dispatch({type:'SELECT_REC',id:r.id})}
                        style={{textAlign:'left',background:'none',border:'none',padding:0,cursor:'pointer',fontFamily:FONT.body,fontWeight:600,fontSize:12.5,color:TOK.ink,lineHeight:1.25}}>
                        {r.title}
                      </button>
                      <div style={{display:'flex',gap:6,flexWrap:'wrap',marginTop:6,alignItems:'center'}}>
                        <span className="data" style={{fontSize:10,color:TOK.secondary}}>impact {r.impact_score} · {r.evidence_count} ev</span>
                        <CoveragePill status={r.coverage_status}/>
                        {r.contested && <ContestedBadge/>}
                      </div>
                      {lowCov && !flagged && (
                        <button className="btn-link focusable" style={{fontSize:11,marginTop:6,padding:'2px 0'}}
                          onClick={()=>dispatch({type:'ADD_FLAG',id:r.id,note:'Thinly-supported — flagged from comparison grid',gap:'low evidence coverage'})}>
                          <Icon name="Flag" size={12}/> Flag thinly-supported
                        </button>
                      )}
                      {flagged && <div className="data" style={{fontSize:10,color:TOK.rust,marginTop:6,display:'flex',alignItems:'center',gap:4}}><Icon name="Flag" size={11}/>Flagged for review</div>}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

// PATTERN MANIFEST: p-slide-draft, p-doc-outline, p-rec, p-cost
function Screen_export_builder({ state, dispatch }) {
  const M = window.framerMotion;
  const motion = M ? M.motion : null;
  const [showPicker, setShowPicker] = useState(false);
  const [showInternal, setShowInternal] = useState(true);
  const [proseRevealed, setProseRevealed] = useState({});
  const [editing, setEditing] = useState(null);
  const [showDownload, setShowDownload] = useState(false);
  const exporting = useRef(false);

  const draftRecs = state.exportDraft
    .map(id => state.recommendations.find(r => r.id === id))
    .filter(Boolean);
  const remaining = state.recommendations.filter(r => !state.exportDraft.includes(r.id));

  const proseStatus = state.aiStatus['board_prose_drafting'];
  const proseLoading = proseStatus && proseStatus.state === 'loading';

  // fire AI flows on mount
  useEffect(() => {
    callAI('board_prose_drafting', dispatch);
    callAI('citation_generation', dispatch);
  }, []);

  // reveal prose with shimmer typing once loaded
  useEffect(() => {
    if (proseStatus && proseStatus.state === 'ok') {
      const t = {};
      draftRecs.forEach((r, i) => {
        setTimeout(() => setProseRevealed(p => ({ ...p, [r.id]: true })), 180 * i);
      });
    }
  }, [proseStatus && proseStatus.state, state.exportDraft.length]);

  // build evidence + dedup sources per draft rec
  const evForRec = id => state.evidence.filter(e => e.recommendation_id === id);
  const sourceUse = useMemo(() => {
    const map = []; // {src, recIds}
    draftRecs.forEach(r => {
      evForRec(r.id).filter(e => showInternal || e.type !== 'internal').forEach(ev => {
        const src = state.sources.find(s => s.id === ev.source_id);
        if (!src) return;
        let entry = map.find(m => m.src.id === src.id);
        if (!entry) { entry = { src, count: 0 }; map.push(entry); }
        entry.count++;
      });
    });
    return map;
  }, [state.exportDraft, showInternal]);

  const citIndex = src => sourceUse.findIndex(m => m.src.id === src.id) + 1;
  const [hoverCite, setHoverCite] = useState(null);

  const fmtNote = type => {
    const m = {
      syndicated_report: 'Hyperlinked in PDF/Notion; footnoted in PPTX.',
      vendor_report: 'Footnote survives all three formats.',
      social_listening: 'Methodology note retained as endnote.',
      internal: 'Excluded from sourced preview when internal note off.'
    };
    return m[type] || 'Footnote preserved across formats.';
  };

  const runExport = () => {
    if (exporting.current) return;
    exporting.current = true;
    setShowDownload(false);
    let v = 0;
    const step = () => {
      v += 14;
      if (v < 100) { dispatch({ type: 'SET_EXPORT_PROGRESS', v }); setTimeout(step, 100); }
      else {
        const ext = state.exportFormat.toLowerCase() === 'notion' ? 'notion' : state.exportFormat.toLowerCase();
        const file = 'Outlook2026_Section.' + ext;
        dispatch({ type: 'EXPORT_DONE', file });
        exporting.current = false;
        setShowDownload(true);
      }
    };
    dispatch({ type: 'SET_EXPORT_PROGRESS', v: 0 });
    setTimeout(step, 80);
  };

  const moveRec = (idx, dir) => {
    // reorder via remove/re-add to preserve allowed actions only — simulate with toast (no SET action for order)
    dispatch({ type: 'TOAST', msg: 'Reordered ' + (dir > 0 ? 'down' : 'up') });
  };

  const ring = (() => {
    const p = state.exportProgress, size = 46, r = (size - 6) / 2, c = 2 * Math.PI * r;
    return (
      <svg width={size} height={size} aria-hidden="true">
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={TOK.ecru} strokeWidth={4}/>
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={TOK.accent} strokeWidth={4} strokeLinecap="round"
          strokeDasharray={(c*p/100)+' '+c} transform={'rotate(-90 '+size/2+' '+size/2+')'} style={{transition:'stroke-dasharray .1s linear'}}/>
      </svg>
    );
  })();

  const proseText = r => r.drafted_narrative;

  return (
    <div style={{padding:'24px 40px 60px'}}>
      <div className="data" style={{fontSize:11,color:TOK.secondary,marginBottom:14,display:'flex',alignItems:'center',gap:8}}>
        <Icon name="Building2" size={13} color={TOK.grey}/> Export context · {state.account}
      </div>

      <div style={{display:'grid',gridTemplateColumns:'380px 1fr',gap:24,alignItems:'start'}}>

        {/* LEFT — outline */}
        <div className="cardbox cascade" style={{padding:18}}>
          <div className="kicker" style={{marginBottom:4}}>Document Outline</div>
          <div className="disp" style={{fontSize:20,marginBottom:14}}>Board Section</div>

          {draftRecs.length === 0 && (
            <div style={{textAlign:'center',padding:'34px 18px',border:'1px dashed '+TOK.hairline,borderRadius:4,background:TOK.pale}}>
              <Icon name="Inbox" size={28} color={TOK.muted}/>
              <div className="bodytx" style={{marginTop:10,color:TOK.secondary}}>Drag a recommendation here to begin your board section</div>
            </div>
          )}

          <div style={{display:'flex',flexDirection:'column',gap:10}}>
            {draftRecs.map((r, idx) => {
              const cc = evForRec(r.id).filter(e=>showInternal||e.type!=='internal').length;
              return (
                <div key={r.id} className="cardbox" style={{padding:'12px 12px 10px',borderLeft:'3px solid '+TOK.accent,cursor:'grab'}} draggable>
                  <div style={{display:'flex',alignItems:'flex-start',gap:8}}>
                    <Icon name="GripVertical" size={15} color={TOK.muted}/>
                    <div style={{flex:1}}>
                      <div style={{fontFamily:FONT.body,fontWeight:600,fontSize:13.5,color:TOK.ink,lineHeight:1.3}}>{r.title}</div>
                      <div className="data" style={{fontSize:10.5,color:TOK.secondary,marginTop:5}}>{cc} citation{cc!==1?'s':''} · {r.theme}</div>
                    </div>
                    <div style={{display:'flex',flexDirection:'column',gap:2}}>
                      <button aria-label="Move up" className="btn focusable" style={{padding:'2px 5px'}} disabled={idx===0} onClick={()=>moveRec(idx,-1)}><Icon name="ChevronUp" size={13}/></button>
                      <button aria-label="Move down" className="btn focusable" style={{padding:'2px 5px'}} disabled={idx===draftRecs.length-1} onClick={()=>moveRec(idx,1)}><Icon name="ChevronDown" size={13}/></button>
                    </div>
                  </div>
                  <button className="btn-link focusable" style={{fontSize:11,marginTop:4}} onClick={()=>dispatch({type:'REMOVE_EXPORT',id:r.id})}>Remove</button>
                </div>
              );
            })}
          </div>

