              {remaining.length===0 && <div className="bodytx" style={{fontSize:12.5,color:TOK.secondary}}>All recommendations added.</div>}
              {remaining.map(r=>(
                <div key={r.id} style={{display:'flex',alignItems:'center',gap:8,padding:'7px 0',borderBottom:'1px solid '+TOK.hairline}}>
                  <div style={{flex:1,fontFamily:FONT.body,fontSize:12.5,color:TOK.body}}>{r.title}</div>
                  <button className="btn focusable" style={{padding:'5px 10px'}} onClick={()=>{dispatch({type:'ADD_EXPORT',id:r.id});}}><Icon name="Plus" size={13}/></button>
                </div>
              ))}
            </div>
          )}

          {/* internal note toggle */}
          <div style={{marginTop:16,paddingTop:14,borderTop:'1px solid '+TOK.hairline}}>
            <label style={{display:'flex',alignItems:'center',gap:9,cursor:'pointer'}}>
              <input type="checkbox" checked={showInternal} onChange={e=>setShowInternal(e.target.checked)} className="focusable"/>
              <span className="lbl" style={{color:TOK.ink}}>Include internal annotations</span>
            </label>
            <div className="bodytx" style={{fontSize:11.5,color:TOK.secondary,marginTop:6}}>Internal notes render in a separated block and can be excluded from the sourced-evidence export.</div>
          </div>
        </div>

        {/* RIGHT — preview */}
        <div style={{display:'flex',flexDirection:'column',gap:18}}>

          {/* format + export bar */}
          <div className="cardbox cascade" style={{padding:16,display:'flex',alignItems:'center',gap:16,flexWrap:'wrap'}}>
            <div>
              <div className="lbl" style={{marginBottom:6}}>Format</div>
              <div style={{display:'flex',gap:6}}>
                {['PPTX','PDF','Notion'].map(f=>(
                  <button key={f} className={'navchip focusable'+(state.exportFormat===f?' on':'')} onClick={()=>dispatch({type:'SET_FORMAT',fmt:f})}>{f}</button>
                ))}
              </div>
            </div>
            <div style={{flex:1}}/>
            <div style={{display:'flex',alignItems:'center',gap:14}}>
              {(state.exportProgress>0 && state.exportProgress<100) && (
                <div style={{display:'flex',alignItems:'center',gap:8}} role="progressbar" aria-valuenow={state.exportProgress} aria-valuemin={0} aria-valuemax={100}>
                  {ring}<span className="data" style={{fontSize:12,color:TOK.secondary}}>{state.exportProgress}%</span>
                </div>
              )}
              {showDownload && state.exportFileName && (
                motion ? (
                  <motion.div initial={{x:30,opacity:0}} animate={{x:0,opacity:1}} className="data"
                    style={{display:'flex',alignItems:'center',gap:7,fontSize:12,padding:'8px 12px',border:'1px solid '+TOK.success,borderRadius:2,color:TOK.success}}>
                    <Icon name="Download" size={14}/>{state.exportFileName}
                  </motion.div>
                ) : (
                  <div className="data" style={{display:'flex',alignItems:'center',gap:7,fontSize:12,padding:'8px 12px',border:'1px solid '+TOK.success,borderRadius:2,color:TOK.success}}>
                    <Icon name="Download" size={14}/>{state.exportFileName}
                  </div>
                )
              )}
              <button className="btn btn-pri focusable" disabled={draftRecs.length===0} onClick={runExport}>
                <Icon name="Send" size={15}/> Export {state.exportFormat}
              </button>
            </div>
          </div>

          {/* board preview */}
          <div className="cardbox cascade" style={{padding:'26px 30px',minHeight:300}}>
            <div className="kicker" style={{marginBottom:4}}>Live Preview · {state.exportFormat}</div>
            <div className="disp" style={{fontSize:26,marginBottom:4}}>Product Innovation Bets for 2026</div>
            <div className="data" style={{fontSize:10.5,color:TOK.secondary,marginBottom:20}}>
              <AIProvenance status={proseStatus}/>
            </div>

            {draftRecs.length===0 && (
              <div className="bodytx" style={{color:TOK.muted}}>Add a recommendation in the outline to draft prose.</div>
            )}

            {draftRecs.map(r=>{
              const revealed = proseRevealed[r.id];
              const evs = evForRec(r.id);
              const internalEvs = evs.filter(e=>e.type==='internal');
              const sourcedEvs = evs.filter(e=>e.type!=='internal');
              return (
                <div key={r.id} style={{marginBottom:26}}>
                  <div style={{fontFamily:FONT.display,fontWeight:600,fontSize:18,color:TOK.ink,marginBottom:8}}>{r.title}</div>

                  {(proseLoading || !revealed) ? (
                    <div aria-busy="true">
                      <div className="shimmer" style={{height:13,borderRadius:4,marginBottom:7,width:'100%'}}/>
                      <div className="shimmer" style={{height:13,borderRadius:4,marginBottom:7,width:'88%'}}/>
                      <div className="shimmer" style={{height:13,borderRadius:4,width:'60%'}}/>
                    </div>
                  ) : (
                    <div
                      contentEditable suppressContentEditableWarning
                      onFocus={()=>setEditing(r.id)} onBlur={()=>setEditing(null)}
                      className="bodytx focusable"
                      style={{fontSize:14,color:TOK.body,outline:'none',borderRadius:2,padding:editing===r.id?'4px':0,boxShadow:editing===r.id?'inset 0 0 0 1px '+TOK.cyan:'none'}}>
                      {proseText(r)}{' '}
                      {sourcedEvs.map(ev=>{
                        const src = state.sources.find(s=>s.id===ev.source_id);
                        const n = src?citIndex(src):0;
                        if(!n) return null;
                        return (
                          <sup key={ev.id}
                            onMouseEnter={()=>setHoverCite(src.id)} onMouseLeave={()=>setHoverCite(null)}
                            style={{cursor:'pointer',color:TOK.cyan,fontFamily:FONT.mono,fontSize:9.5,padding:'0 1px',background:hoverCite===src.id?TOK.washCool:'transparent',borderRadius:2}}>[{n}]</sup>
                        );
                      })}
                    </div>
                  )}

                  {/* internal note block */}
                  {showInternal && internalEvs.length>0 && (
                    <div style={{marginTop:12,background:TOK.ecru,borderLeft:'3px solid '+TOK.slate,borderRadius:2,padding:'10px 14px'}}>
                      <div className="lbl" style={{color:TOK.slate,marginBottom:6}}>Internal note (excludable)</div>
                      {internalEvs.map(ev=>(
                        <div key={ev.id} className="bodytx" style={{fontSize:12.5,color:TOK.secondary}}>{ev.pull_quote}</div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}

            {/* citation appendix */}
            {sourceUse.length>0 && (
              <div style={{marginTop:14,paddingTop:18,borderTop:'1px solid '+TOK.hairline}}>
                <div className="lbl" style={{marginBottom:4}}>Citation Appendix</div>
                <div className="data" style={{fontSize:10,color:TOK.secondary,marginBottom:12}}>
                  <AIProvenance status={state.aiStatus['citation_generation']}/> · deduplicated, 100% footnoted
                </div>
                <ol style={{listStyle:'none',padding:0,margin:0,display:'flex',flexDirection:'column',gap:10}}>
                  {sourceUse.map((m,i)=>(
                    <li key={m.src.id}
                      onMouseEnter={()=>setHoverCite(m.src.id)} onMouseLeave={()=>setHoverCite(null)}
                      style={{display:'flex',gap:10,padding:'9px 11px',borderRadius:2,background:hoverCite===m.src.id?TOK.washCool:TOK.pale,border:'1px solid '+(hoverCite===m.src.id?TOK.cyan:TOK.hairline)}}>
                      <span className="data" style={{fontSize:11,color:TOK.cyan,minWidth:22}}>[{i+1}]</span>
                      <div style={{flex:1}}>
                        <div style={{fontFamily:FONT.body,fontWeight:600,fontSize:12.5,color:TOK.ink}}>{m.src.publisher} — {m.src.title}</div>
                        <div className="data" style={{fontSize:10.5,color:TOK.secondary,marginTop:3}}>{m.src.publish_date} · {m.src.type.replace(/_/g,' ')} · quality {m.src.quality_weight.toFixed(2)} · used {m.count}×</div>
                        <div className="bodytx" style={{fontSize:11.5,color:TOK.secondary,marginTop:4}}>{m.src.methodology_note}</div>
                        <div className="data" style={{fontSize:10,color:TOK.grey,marginTop:4,display:'flex',alignItems:'center',gap:5}}><Icon name="FileCheck" size={11} color={TOK.grey}/>{fmtNote(m.src.type)}</div>
                      </div>
                    </li>
                  ))}
                </ol>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// PATTERN MANIFEST: p-diff (proto/Compare-style changelog table), p-trans (cross-fade arrows), p-rec (recommendation rows), proto/Stat, proto/Badge
function Screen_refresh_diff_view({ state, dispatch }){
  useEffect(()=>{
    callAI('cross_source_synthesis',dispatch);
    callAI('confidence_coverage_scoring',dispatch);
  },[]);

  const changed = state.diff.filter(d=>d.arrow!=='flat');
  const unchanged = state.diff.filter(d=>d.arrow==='flat');
  const changedIds = changed.map(d=>d.rec_id);

  const arrowMeta = {
    up:{col:TOK.success,icon:'ArrowUpRight',lbl:'rose'},
    down:{col:TOK.rust,icon:'ArrowDownRight',lbl:'fell'},
    flat:{col:TOK.grey,icon:'Minus',lbl:'unchanged'}
  };

  function DiffArrow({d}){
    const m=arrowMeta[d.arrow];
    const [show,setShow]=useState(false);
    useEffect(()=>{ const t=setTimeout(()=>setShow(true),120); return ()=>clearTimeout(t); },[]);
    return (
      <div style={{display:'flex',alignItems:'center',gap:10}}>
        <span className="data" style={{fontSize:15,color:TOK.muted,opacity:show?0.45:1,transition:'opacity .6s ease'}}>{d.before.toFixed(2)}</span>
        <span style={{color:m.col,display:'inline-flex',transition:'transform .5s ease',transform:show?'none':'translateX(-6px)'}}><Icon name={m.icon} size={16}/></span>
        <span className="data" style={{fontSize:17,fontWeight:600,color:m.col,opacity:show?1:0,transition:'opacity .6s ease'}}>{d.after.toFixed(2)}</span>
      </div>
    );
  }

  function Row({d}){
    const rec = state.recommendations.find(r=>r.id===d.rec_id);
    const m=arrowMeta[d.arrow];
    const dimmed = d.arrow==='flat';
    return (
      <div className="cascade" style={{
        padding:'18px 22px',borderBottom:'1px solid '+TOK.hairline,
        background:dimmed?TOK.pale:TOK.paper,opacity:dimmed?0.5:1,
        display:'grid',gridTemplateColumns:'1fr 220px',gap:24,alignItems:'center'
      }}>
        <div>
          <div style={{display:'flex',alignItems:'center',gap:10,marginBottom:8}}>
            <div className="disp" style={{fontSize:18,color:TOK.ink}}>{d.title}</div>
            {dimmed
              ? <span className="data" style={{fontSize:10.5,padding:'3px 8px',borderRadius:999,border:'1px solid '+TOK.grey,color:TOK.grey}}>● unchanged</span>
              : <span className="data" style={{fontSize:10.5,padding:'3px 8px',borderRadius:999,border:'1px solid '+m.col,color:m.col,display:'inline-flex',alignItems:'center',gap:4}}><span style={{width:7,height:7,borderRadius:999,background:m.col}}/>confidence {m.lbl}</span>}
          </div>
          <div className="bodytx" style={{fontSize:13,color:TOK.secondary,display:'flex',gap:8,alignItems:'flex-start'}}>
            <span style={{color:m.col,marginTop:1,flexShrink:0}}><Icon name="Activity" size={13}/></span>
            <span><b style={{color:TOK.ink,fontWeight:600}}>Driver:</b> {d.driver}</span>
          </div>
          {!dimmed && (
            <button className="btn-link focusable" style={{marginTop:6,fontSize:12.5}} onClick={()=>dispatch({type:'SELECT_REC',id:d.rec_id})}>
              <Icon name="FileSearch" size={13}/> View evidence
            </button>
          )}
        </div>
        <div style={{justifySelf:'end'}}>
          <DiffArrow d={d}/>
        </div>
      </div>
    );
  }

  return (
    <div style={{maxWidth:1080,margin:'0 auto',padding:'28px 40px 80px'}}>
      <div style={{display:'flex',alignItems:'flex-start',justifyContent:'space-between',marginBottom:6}}>
        <div>
          <div className="kicker" style={{marginBottom:6}}>Changelog · Re-ingest</div>
          <h1 className="disp" style={{fontSize:32,color:TOK.ink}}>Refreshed against new data</h1>
        </div>
        <div style={{textAlign:'right'}}>
          <div className="lbl" style={{marginBottom:4}}>Last refresh</div>
          <div className="data" style={{fontSize:13,color:TOK.ink}}>{state.lastRefresh}</div>
          <div style={{marginTop:6}}><AIProvenance status={state.aiStatus.cross_source_synthesis}/></div>
        </div>
      </div>

      {/* recovery note — session-24 */}
      <div style={{display:'flex',alignItems:'center',gap:8,padding:'9px 12px',background:TOK.washCool,border:'1px solid '+TOK.hairline,borderRadius:2,marginTop:14,marginBottom:20}}>
        <Icon name="ShieldCheck" size={15} color={TOK.teal}/>
        <span className="bodytx" style={{fontSize:12.5,color:TOK.ink}}><b>Draft preserved.</b> Your in-progress export selections survived the refresh.</span>
      </div>

      {/* stat strip */}
      <div style={{display:'flex',gap:14,marginBottom:22}}>
        <div className="cardbox" style={{flex:1,padding:'14px 18px'}}>
          <div className="lbl" style={{marginBottom:6}}>Recommendations moved</div>
          <div className="data" style={{fontSize:22,fontWeight:600,color:TOK.ink}}>{changed.length}<span style={{fontSize:13,color:TOK.muted,fontWeight:400}}> / {state.diff.length}</span></div>
        </div>
        <div className="cardbox" style={{flex:1,padding:'14px 18px'}}>
          <div className="lbl" style={{marginBottom:6}}>Confidence rose</div>
          <div className="data" style={{fontSize:22,fontWeight:600,color:TOK.success}}>{changed.filter(d=>d.arrow==='up').length}</div>
        </div>
        <div className="cardbox" style={{flex:1,padding:'14px 18px'}}>
          <div className="lbl" style={{marginBottom:6}}>Confidence fell</div>
          <div className="data" style={{fontSize:22,fontWeight:600,color:TOK.rust}}>{changed.filter(d=>d.arrow==='down').length}</div>
        </div>
      </div>

      <div className="cardbox" style={{overflow:'hidden'}}>
        <div style={{display:'grid',gridTemplateColumns:'1fr 220px',gap:24,padding:'10px 22px',background:TOK.panel,borderBottom:'1px solid '+TOK.hairline}}>
          <div className="lbl">Recommendation · driver</div>
          <div className="lbl" style={{justifySelf:'end'}}>Before → After</div>
        </div>
        {changed.map(d=><Row key={d.rec_id} d={d}/>)}
        {unchanged.map(d=><Row key={d.rec_id} d={d}/>)}
      </div>

      {/* footer — re-export scoped to changed */}
      <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginTop:24,padding:'16px 20px',background:TOK.paper,border:'1px solid '+TOK.hairline,borderRadius:2}}>
        <div className="bodytx" style={{fontSize:13,color:TOK.secondary}}>
          Re-export will include only the <b style={{color:TOK.ink}}>{changedIds.length} changed</b> section{changedIds.length===1?'':'s'}: {changed.map(d=>d.rec_id).join(', ')}.
        </div>
        <button className="btn btn-pri focusable" disabled={changedIds.length===0} onClick={()=>{
          changedIds.forEach(id=>dispatch({type:'ADD_EXPORT',id}));
          dispatch({type:'NAV',screen:'export_builder'});
        }}>
          <Icon name="FileOutput" size={15}/> Re-export changed sections
        </button>
      </div>
    </div>
  );
}

// PATTERN MANIFEST: p-rail, p-triage, p-hitl, p-chart
// Catalog patterns used: proto/Chips, proto/Badge, proto/List, proto/Empty, proto/Stat (sparkline), proto/Progress (threshold)
function Screen_rising_signals_and_flags({ state, dispatch }) {
  const tab = state.signalsTab;
  const [hovered, setHovered] = useState(null);

  const setTab = (t) => dispatch({ type: 'SIGNALS_TAB', tab: t });

  const Sparkline = ({ spark, animate }) => {
    const w = 120, h = 34, pad = 3;
    const min = Math.min(...spark), max = Math.max(...spark);
    const rng = max - min || 1;
    const pts = spark.map((v, i) => {
      const x = pad + (i / (spark.length - 1)) * (w - pad * 2);
      const y = h - pad - ((v - min) / rng) * (h - pad * 2);
      return [x, y];
    });
    const d = pts.map((p, i) => (i === 0 ? 'M' : 'L') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' ');
    const len = 200;
    return (
      <svg width={w} height={h} aria-hidden="true" style={{ display: 'block' }}>
        <polyline points={pts.map(p => p.join(',')).join(' ')} fill="none" stroke={TOK.cyan} strokeWidth={1.6}
          strokeLinecap="round" strokeLinejoin="round"
          style={animate ? { strokeDasharray: len, strokeDashoffset: 0, animation: 'drawLine .7s ease both', '--len': len } : {}} />
        <circle cx={pts[pts.length - 1][0]} cy={pts[pts.length - 1][1]} r={2.6} fill={TOK.cyan} />
      </svg>
    );
  };

  const onSetWatch = (id, threshold) => {
    dispatch({ type: 'SET_WATCH', id, threshold });
    callAI('emerging_theme_watch', dispatch);
  };

  // Fire gap-detection context once when entering flags tab
  useEffect(() => {
    if (tab === 'flags') callAI('evidence_recommendation_linking', dispatch);
  }, [tab]);

  const openFlags = state.flags.filter(f => f.status === 'open');
  const resolvedFlags = state.flags.filter(f => f.status === 'resolved');
  const recTitle = (id) => (state.recommendations.find(r => r.id === id) || {}).title || id;

  return (
    <div style={{ maxWidth: 1080, margin: '0 auto', padding: '28px 40px 80px' }}>
      <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', marginBottom: 18 }}>
        <div>
          <div className="kicker" style={{ marginBottom: 6 }}>Watch Tray · Triage</div>
          <h1 className="disp" style={{ fontSize: 30, color: TOK.ink }}>Rising Signals &amp; Flag Queue</h1>
        </div>
        <div style={{ display: 'flex', gap: 12 }}>
          <AIProvenance status={state.aiStatus['emerging_theme_watch']} />
          <AIProvenance status={state.aiStatus['evidence_recommendation_linking']} />
        </div>
      </div>

      {/* Tabs as chips */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 22 }}>
        {[['rising', 'Rising Signals', state.watch.length], ['flags', 'Flag Queue', openFlags.length]].map(([id, lbl, n]) => {
          const on = tab === id;
          return (
            <button key={id} className="focusable" aria-pressed={on} onClick={() => setTab(id)}
              style={{
                fontFamily: FONT.mono, fontSize: 11.5, letterSpacing: 1.2, textTransform: 'uppercase',
                padding: '8px 14px', borderRadius: 999, cursor: 'pointer',
                background: on ? TOK.panel : TOK.paper,
                border: on ? '1.5px solid ' + TOK.accent : '1px solid ' + TOK.hairline,
                color: on ? TOK.ink : TOK.grey, display: 'inline-flex', alignItems: 'center', gap: 7
              }}>
              {lbl}
              <span className="data" style={{ fontSize: 10.5, color: on ? TOK.ink : TOK.muted }}>· {n}</span>
            </button>
          );
        })}
      </div>

      {tab === 'rising' && (
        <div>
          {state.watch.length === 0 ? (
            <EmptyTray msg="No emerging themes above noise floor" />
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
              {state.watch.map((w, i) => {
                const col = w.current_confidence >= 0.8 ? TOK.success : w.current_confidence >= 0.65 ? TOK.cyan : w.current_confidence >= 0.5 ? TOK.warn : TOK.error;
                const momUp = w.momentum === 'rising';
                return (
                  <div key={w.id} className="cardbox cascade"
                    onMouseEnter={() => setHovered(w.id)} onMouseLeave={() => setHovered(null)}
                    style={{
                      padding: 18, animationDelay: (i * 60) + 'ms',
                      borderLeft: w.triggered ? '3px solid ' + TOK.rust : '1px solid ' + TOK.hairline,
                      background: w.triggered ? TOK.washWarn : TOK.paper
                    }}>
                    <div style={{ display: 'flex', gap: 20, alignItems: 'flex-start' }}>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8, flexWrap: 'wrap' }}>
                          <span style={{ fontFamily: FONT.display, fontWeight: 600, fontSize: 18, color: TOK.ink }}>{w.theme}</span>
                          {/* momentum badge */}
                          <span className="data" style={{ fontSize: 10.5, padding: '3px 8px', borderRadius: 999, border: '1px solid ' + (momUp ? TOK.success : TOK.grey), color: momUp ? TOK.success : TOK.grey, display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                            <Icon name={momUp ? 'TrendingUp' : 'Minus'} size={11} />{momUp ? 'Rising' : 'Flat'}
                          </span>
                          {w.triggered && (
                            <span className="data" style={{ fontSize: 10.5, padding: '3px 8px', borderRadius: 999, background: TOK.rust, color: TOK.paper, display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                              <Icon name="Bell" size={11} />Watch crossed
                            </span>
                          )}
                        </div>

                        <div style={{ display: 'flex', alignItems: 'center', gap: 16, marginBottom: 14 }}>
                          <div>
                            <div className="lbl" style={{ marginBottom: 2 }}>Confidence</div>
                            <span className="data" style={{ fontSize: 20, color: col, fontWeight: 500 }}>{w.current_confidence.toFixed(2)}</span>
                          </div>
                          <div style={{ width: 1, height: 30, background: TOK.hairline }} />
                          <div>
                            <div className="lbl" style={{ marginBottom: 2 }}>Threshold</div>
                            <span className="data" style={{ fontSize: 20, color: TOK.secondary, fontWeight: 500 }}>{w.threshold.toFixed(2)}</span>
                          </div>
                        </div>

                        {/* threshold slider */}
                        <div style={{ maxWidth: 360 }}>
                          <input type="range" min={0.3} max={0.95} step={0.01} value={w.threshold}
                            className="focusable"
                            aria-label={'Watch threshold for ' + w.theme}
                            onChange={(e) => onSetWatch(w.id, parseFloat(e.target.value))}
                            style={{ width: '100%', accentColor: TOK.accent, cursor: 'pointer' }} />
                          <div className="data" style={{ fontSize: 10.5, color: TOK.muted, marginTop: 3 }}>
                            {w.current_confidence >= w.threshold ? 'Above threshold — alert active' : 'Below threshold by ' + (w.threshold - w.current_confidence).toFixed(2)}
                          </div>
                        </div>

                        <button className="btn-link focusable" style={{ marginTop: 8, paddingLeft: 0 }}
                          onClick={() => dispatch({ type: 'SELECT_THEME', theme: w.theme })}>
                          Open sentiment series →
                        </button>
                      </div>

                      <div style={{ paddingTop: 4 }}>
                        <div className="lbl" style={{ marginBottom: 4, textAlign: 'right' }}>30-day trend</div>
                        <Sparkline spark={w.spark} animate={hovered === w.id} />
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {tab === 'flags' && (
        <div>
          {openFlags.length === 0 && resolvedFlags.length === 0 ? (
            <EmptyTray msg="No open flags" />
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
              {openFlags.length === 0 && <EmptyTray msg="No open flags" />}
              {openFlags.map((f, i) => (
                <div key={f.id} className="cardbox cascade" style={{ padding: 18, animationDelay: (i * 60) + 'ms', borderLeft: '3px solid ' + TOK.warn }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 16 }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 6, flexWrap: 'wrap' }}>
                        <Icon name="Flag" size={15} color={TOK.warn} />
                        <span style={{ fontFamily: FONT.display, fontWeight: 600, fontSize: 17, color: TOK.ink }}>{recTitle(f.recommendation_id)}</span>
                        <span className="data" style={{ fontSize: 10, padding: '2px 7px', borderRadius: 999, border: '1px solid ' + TOK.warn, color: TOK.warn }}>OPEN</span>
                      </div>
                      <p className="bodytx" style={{ marginBottom: 10, color: TOK.body }}>{f.note}</p>
                      <div style={{ display: 'flex', gap: 18, flexWrap: 'wrap', alignItems: 'center' }}>
                        <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                          <Icon name="User" size={13} color={TOK.grey} />
                          <span className="data" style={{ fontSize: 11.5, color: TOK.secondary }}>{f.assignee}</span>
                        </div>
                        <span className="data" style={{ fontSize: 10.5, padding: '3px 9px', borderRadius: 999, background: TOK.washCool, border: '1px solid ' + TOK.cyan, color: TOK.teal, display: 'inline-flex', alignItems: 'center', gap: 5 }}>
                          <Icon name="Sparkles" size={11} />AI gap · {f.gap_reason}
                        </span>
                      </div>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 8, alignItems: 'flex-end' }}>
                      <button className="btn focusable" onClick={() => dispatch({ type: 'SELECT_REC', id: f.recommendation_id })}>
                        <Icon name="FileSearch" size={14} />Open evidence
                      </button>
                      <button className="btn btn-pri focusable" onClick={() => dispatch({ type: 'RESOLVE_FLAG', id: f.id })}>
                        <Icon name="Check" size={14} />Resolve
                      </button>
                    </div>
                  </div>
                </div>
              ))}

              {resolvedFlags.length > 0 && (
                <div style={{ marginTop: 12 }}>
                  <div className="lbl" style={{ marginBottom: 8 }}>Resolved · {resolvedFlags.length}</div>
                  {resolvedFlags.map(f => (
                    <div key={f.id} className="cardbox" style={{ padding: 14, marginBottom: 8, opacity: 0.55, borderLeft: '3px solid ' + TOK.success }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
                        <Icon name="CheckCircle" size={14} color={TOK.success} />
                        <span style={{ fontFamily: FONT.display, fontWeight: 600, fontSize: 15, color: TOK.ink }}>{recTitle(f.recommendation_id)}</span>
                        <span className="data" style={{ fontSize: 10, padding: '2px 7px', borderRadius: 999, border: '1px solid ' + TOK.success, color: TOK.success }}>RESOLVED</span>
                        <span className="bodytx" style={{ fontSize: 12.5, color: TOK.muted }}>{f.note}</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function EmptyTray({ msg }) {
  return (
    <div className="cardbox" style={{ padding: '40px 28px', textAlign: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 10 }}>
      <Icon name="Inbox" size={30} color={TOK.muted} />
      <div style={{ fontFamily: FONT.body, fontWeight: 600, fontSize: 14, color: TOK.ink }}>{msg}</div>
      <div className="bodytx" style={{ fontSize: 12.5, color: TOK.muted }}>Nothing requires attention right now.</div>
    </div>
  );
}
